const body = $('Leave webhook').first().json.body;
const today = $now.setZone('Asia/Seoul').toFormat('yyyy-MM-dd');
const isDate = s => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && !isNaN(Date.parse(s + 'T00:00:00Z')) && new Date(s + 'T00:00:00Z').toISOString().slice(0, 10) === s;
const dayKo = s => '일월화수목금토'[new Date(s + 'T00:00:00Z').getUTCDay()];
const addDays = (s, n) => new Date(Date.parse(s + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
const daysBetween = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
// LLM이 날짜를 지어내지 않았는지: 요청 문장에 날짜를 말하는 표현이 있어야 날짜를 믿는다
const mentionsDate = text => /\d{1,2}\s*월|\d{1,2}\s*일|\d{4}-\d{1,2}-\d{1,2}|\d{1,2}\/\d{1,2}|오늘|내일|모레|글피|요일|이번\s*주|다음\s*주|주말|월말|월초/.test(String(text ?? ''));
const range = (a, b) => (!b || a === b) ? `${a}(${dayKo(a)})` : `${a}(${dayKo(a)}) ~ ${b}(${dayKo(b)})`;
const won = n => Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',') + '원';
const hash = s => { let h = 5381; for (const c of s) h = ((h * 33) ^ c.codePointAt(0)) >>> 0; return h.toString(36).toUpperCase().slice(-4).padStart(4, '0'); };
// 연습용 가짜 인사 데이터 (2026년)
const LEAVE = { '박서연': { total: 15, used: 6 }, '이준호': { total: 15, used: 14.5 }, '김민지': { total: 20, used: 3 } };
const user = String(body.user).trim();
const kind = String(body.kind ?? '').includes('반차') ? '반차' : '연차';
const half = ['오전', '오후'].includes(String(body.half ?? '').trim()) ? String(body.half).trim() : '';
const start = String(body.start ?? '').trim();
let end = String(body.end ?? '').trim() || start;
if (kind === '반차') end = start;
const out = (route, answer, extra = {}) => [{ json: { route, answer, user, kind, ...extra } }];
if (!isDate(start) || !isDate(end)) return out('입력 필요', '휴가 날짜를 알려 주세요. 예: "11월 6일 연차", "11월 10일부터 11일까지 연차", "11월 6일 오후 반차"');
if (end < start) return out('입력 필요', `끝 날짜(${end})가 시작 날짜(${start})보다 빠릅니다.`);
if (daysBetween(start, end) > 30) return out('담당자 연결', '30일이 넘는 휴가는 인사팀과 직접 상의해 주세요.');
let days = 0;
for (let d = start; d <= end; d = addDays(d, 1)) { const w = new Date(d + 'T00:00:00Z').getUTCDay(); if (w !== 0 && w !== 6) days += 1; }
if (days === 0) return out('거절', `${range(start, end)}은 주말이라 연차를 쓰지 않아도 됩니다.`);
if (kind === '반차') days = 0.5;
const lead = daysBetween(today, start);
if (lead < 3) return out('거절', `연차는 사용일 3일 전까지 신청해야 해요 (HR-1). ${range(start)}은 오늘(${range(today)})로부터 ${lead}일 ${lead < 0 ? '지난 날' : '뒤'}라 접수하지 못했습니다. 급한 일이면 팀장에게 직접 말씀해 주세요.`);
const row = LEAVE[user];
if (!row) return out('담당자 연결', `${user} 님의 연차 기록을 찾지 못해 인사팀에 연결했습니다.`);
const remaining = row.total - row.used;
if (days > remaining) return out('거절', `남은 연차가 ${remaining}일이라 ${days}일을 신청할 수 없어요. 날짜를 줄이거나 반차로 바꿔 다시 신청해 주세요.`, { days, remaining });
const label = kind === '반차' ? `${half ? half + ' ' : ''}반차` : '연차';
const request_id = `L-${start.replace(/-/g, '')}-${hash(user + kind + half + end)}`;
return out('접수 완료', `${range(start, end)} ${label} ${days}일 신청을 접수했습니다 (접수 번호 ${request_id}). 팀장 승인 후 확정되며, 승인되면 남은 연차는 ${remaining - days}일이에요.`,
  { request_id, start, end, half, days, remaining_after: remaining - days });
